<?php declare(strict_types=1); namespace App\Application\Arena\Service; use App\Application\Performance\Port\TransactionManagerInterface;use App\Domain\Arena\Entity\DuelAnswer;use App\Domain\Arena\Enum\DuelStatus;use App\Domain\Arena\Repository\DuelAnswerVerifierInterface;use App\Domain\Arena\Repository\DuelRepositoryInterface;final class AnswerDuelService { public function __construct(private readonly DuelRepositoryInterface $duels,private readonly DuelAnswerVerifierInterface $verifier,private readonly TransactionManagerInterface $transactions,private readonly \DateTimeZone $utc=new \DateTimeZone('UTC')){}public function answer(string $duelId,string $userId,string $optionId):bool{return $this->transactions->transactional(function()use($duelId,$userId,$optionId){$d=$this->duels->findForParticipant($duelId,$userId);$now=new \DateTimeImmutable('now',$this->utc);if(!$d||$d->status!==DuelStatus::QUESTION_OPEN||$d->deadlineAt===null||$now>$d->deadlineAt)throw new \DomainException('Questão não aceita resposta.');$correct=$this->verifier->verify($duelId,$d->currentPosition,$optionId);if($correct===null)throw new \DomainException('Alternativa inválida.');$elapsed=max(0,(int)(($now->format('U.u')-$d->openedAt?->format('U.u'))*1000));return $this->duels->appendAnswer(new DuelAnswer($this->uuid(),$duelId,$d->currentPosition,$userId,$optionId,$now,$elapsed,$correct));});}private function uuid():string{$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));}}
